const test = require('node:test');
const assert = require('node:assert/strict');
const { createLabelCache } = require('../labels.cjs');
test('pair boundaries cannot collide', () => {
  const c = createLabelCache();
  const pairs = [
    ['team|east','fr','Bonjour'], ['team','east|fr','Salut'],
    ['','|','left'], ['|','','right'],
    ['a','b','forward'], ['b','a','reverse'],
    ['中"','\\n','unicode'], ['中','"\\n','other']
  ];
  for (const [tenant, locale, value] of pairs) c.set(tenant, locale, value);
  for (const [tenant, locale, value] of pairs) assert.equal(c.get(tenant, locale), value);
  c.set('team','east|fr','Updated');
  assert.equal(c.get('team|east','fr'), 'Bonjour');
  assert.equal(c.get('team','east|fr'), 'Updated');
  assert.equal(c.get('missing','fr'), undefined);
});
test('empty pair and independent instances', () => {
  const a = createLabelCache(), b = createLabelCache();
  a.set('','','empty');
  assert.equal(a.get('',''), 'empty');
  assert.equal(b.get('',''), undefined);
});

test('changing the separator or ambiguously escaping it is insufficient', () => {
  const c = createLabelCache();
  const pairs = [];
  for (const separator of [':', '/', ',', ';', '\\', '\0', '\n', '::', '💡']) {
    pairs.push(['west' + separator + 'team', 'en', 'left:' + separator]);
    pairs.push(['west', 'team' + separator + 'en', 'right:' + separator]);
  }
  pairs.push(['a\\', '|b', 'slash-left'], ['a\\|', 'b', 'slash-right']);
  pairs.push(['é', 'en', 'composed'], ['e\u0301', 'en', 'decomposed']);
  for (const [tenant,locale,label] of pairs) c.set(tenant,locale,label);
  for (const [tenant,locale,label] of pairs) assert.equal(c.get(tenant,locale), label);
});

