function cacheKey(tenant, locale) {
  return JSON.stringify([tenant, locale]);
}
function createLabelCache() {
  const entries = new Map();
  return {
    set(tenant, locale, label) { entries.set(cacheKey(tenant, locale), label); },
    get(tenant, locale) { return entries.get(cacheKey(tenant, locale)); }
  };
}
module.exports = { createLabelCache };
